const a=(t,e=0)=>t==null||Number.isNaN(t)?"-":t.toLocaleString("en-US",{maximumFractionDigits:e,minimumFractionDigits:e}),i=(t,e="USD")=>t.toLocaleString("en-US",{style:"currency",currency:e,maximumFractionDigits:2});function u(t){return t==null||Number.isNaN(t)?"-":t<1e3?`${Math.round(t)} ms`:t<6e4?`${(t/1e3).toFixed(1)} s`:`${(t/6e4).toFixed(1)} min`}const c=t=>{const e=new Date(t);return Number.isNaN(e.getTime())?"-":e.toLocaleTimeString("en-GB",{hour12:!1})};function s(t,e=Date.now()){const n=Math.max(0,Math.round((e-new Date(t).getTime())/1e3));return n<60?`${n}s ago`:n<3600?`${Math.floor(n/60)}m ago`:`${Math.floor(n/3600)}h ago`}function f(t){const e=t.reduce((r,o)=>r+Number(o.count),0);return e===0?null:t.filter(r=>r.status==="RESERVED").reduce((r,o)=>r+Number(o.count),0)/e*100}function m(t,e=70,n=85){return t>=n?"bad":t>=e?"warn":"ok"}export{s as a,a as b,i as c,u as d,c as f,f as s,m as t};
